// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
import { default as handler } from "./.open-next/worker.js";
import { cleanupExpiredContactSubmissions } from "./src/lib/contact-ledger";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.hostname === "www.patchworks.ai") {
      url.protocol = "https:";
      url.hostname = "patchworks.ai";
      url.port = "";
      return Response.redirect(url, 308);
    }

    const response = await handler.fetch(request, env, ctx);
    if (env.ENVIRONMENT !== "preview" && !url.hostname.endsWith(".workers.dev"))
      return response;

    const headers = new Headers(response.headers);
    headers.set("X-Robots-Tag", "noindex, nofollow");
    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  },

  async scheduled(_event, env) {
    try {
      const deleted = await cleanupExpiredContactSubmissions(env.CONTACT_DB);
      console.log(
        JSON.stringify({ event: "contact_ledger_cleanup_complete", deleted }),
      );
    } catch {
      console.error(JSON.stringify({ event: "contact_ledger_cleanup_failed" }));
      throw new Error("Contact ledger cleanup failed");
    }
  },
} satisfies ExportedHandler<CloudflareEnv>;

// OpenNext's cache Durable Objects must remain exported by a custom entrypoint.
// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
